export type TaskLedgerEventType =
  | 'task.submitted'
  | 'task.accepted'
  | 'task.rejected'
  | 'task.started'
  | 'task.completed'
  | 'task.failed'
  | 'task.cancelled';

export type TaskLedgerTaskStatus =
  | 'pending'
  | 'accepted'
  | 'rejected'
  | 'running'
  | 'completed'
  | 'failed'
  | 'cancelled';

export interface TaskLedgerEvent {
  eventId: string;
  eventType: TaskLedgerEventType;
  workspaceId: string;
  taskId: string;
  batchIdempotencyKey?: string;
  occurredAt: string;
  payload?: Record<string, unknown>;
}

export interface TaskLedgerTaskView {
  taskId: string;
  workspaceId: string;
  status: TaskLedgerTaskStatus;
  eventCount: number;
  submittedAt?: string;
  updatedAt: string;
  batchIdempotencyKey?: string;
  payload?: Record<string, unknown>;
}

export interface TaskLedgerWorkingContextView {
  workspaceId: string;
  tasks: TaskLedgerTaskView[];
  pending: TaskLedgerTaskView[];
  accepted: TaskLedgerTaskView[];
}

export const TASK_LEDGER_WORKING_CONTEXT_VERSION = 1;

export function taskLedgerEventKey(event: Pick<TaskLedgerEvent, 'workspaceId' | 'batchIdempotencyKey'>): string | undefined {
  if (!event.batchIdempotencyKey) return undefined;
  return `${event.workspaceId}\u0000${event.batchIdempotencyKey}`;
}

export function isDuplicateTaskLedgerEvent(
  events: readonly TaskLedgerEvent[],
  event: TaskLedgerEvent,
): boolean {
  const key = taskLedgerEventKey(event);
  if (!key) return false;
  return events.some((candidate) => taskLedgerEventKey(candidate) === key);
}

export function appendTaskLedgerEvent(
  events: readonly TaskLedgerEvent[],
  event: TaskLedgerEvent,
): { events: TaskLedgerEvent[]; appended: boolean } {
  if (isDuplicateTaskLedgerEvent(events, event)) {
    return { events: [...events], appended: false };
  }
  return { events: [...events, event], appended: true };
}

export function projectTaskLedger(
  events: readonly TaskLedgerEvent[],
  workspaceId: string,
): TaskLedgerWorkingContextView {
  const tasks = new Map<string, TaskLedgerTaskView>();

  for (const event of events) {
    if (event.workspaceId !== workspaceId) continue;

    let task = tasks.get(event.taskId);
    if (!task) {
      task = {
        taskId: event.taskId,
        workspaceId: workspaceId,
        status: 'pending',
        eventCount: 0,
        updatedAt: event.occurredAt,
      };
      tasks.set(event.taskId, task);
    }

    task.eventCount += 1;
    task.updatedAt = event.occurredAt;
    if (event.batchIdempotencyKey) task.batchIdempotencyKey = event.batchIdempotencyKey;
    if (event.payload) task.payload = { ...task.payload, ...event.payload };

    switch (event.eventType) {
      case 'task.submitted':
        task.status = 'pending';
        task.submittedAt = event.occurredAt;
        break;
      case 'task.accepted':
        task.status = 'accepted';
        break;
      case 'task.rejected':
        task.status = 'rejected';
        break;
      case 'task.started':
        task.status = 'running';
        break;
      case 'task.completed':
        task.status = 'completed';
        break;
      case 'task.failed':
        task.status = 'failed';
        break;
      case 'task.cancelled':
        task.status = 'cancelled';
        break;
    }
  }

  const ordered = [...tasks.values()].sort((left, right) => {
    const byTime = (left.submittedAt ?? left.updatedAt).localeCompare(right.submittedAt ?? right.updatedAt);
    return byTime || left.taskId.localeCompare(right.taskId);
  });

  return {
    workspaceId,
    tasks: ordered,
    pending: ordered.filter((task) => task.status === 'pending'),
    accepted: ordered.filter((task) => task.status === 'accepted'),
  };
}

export function emptyTaskLedgerWorkingContextView(workspaceId: string): TaskLedgerWorkingContextView {
  return { workspaceId, tasks: [], pending: [], accepted: [] };
}

import { promises as fs } from 'node:fs';
import path from 'node:path';
import {
  appendTaskLedgerEvent,
  emptyTaskLedgerWorkingContextView,
  isDuplicateTaskLedgerEvent,
  projectTaskLedger,
  type TaskLedgerEvent,
  type TaskLedgerWorkingContextView,
} from '../../shared/task-ledger-working-context';

export type {
  TaskLedgerEvent,
  TaskLedgerEventType,
  TaskLedgerTaskStatus,
  TaskLedgerTaskView,
  TaskLedgerWorkingContextView,
} from '../../shared/task-ledger-working-context';

export interface TaskLedgerWorkingContextOptions {
  workspaceRoot: string;
  ledgerFileName?: string;
}

export interface AppendTaskLedgerEventResult {
  appended: boolean;
  event: TaskLedgerEvent;
  view: TaskLedgerWorkingContextView;
}

export class TaskLedgerWorkingContext {
  private readonly workspaceRoot: string;
  private readonly ledgerFileName: string;

  constructor(options: TaskLedgerWorkingContextOptions) {
    if (!options.workspaceRoot) throw new Error('workspaceRoot is required');
    this.workspaceRoot = path.resolve(options.workspaceRoot);
    this.ledgerFileName = options.ledgerFileName ?? 'task-ledger.jsonl';
  }

  get ledgerPath(): string {
    return path.join(this.workspaceRoot, this.ledgerFileName);
  }

  async append(event: TaskLedgerEvent): Promise<AppendTaskLedgerEventResult> {
    const events = await this.readEvents();
    if (isDuplicateTaskLedgerEvent(events, event)) {
      return {
        appended: false,
        event,
        view: projectTaskLedger(events, event.workspaceId),
      };
    }

    await fs.mkdir(this.workspaceRoot, { recursive: true });
    await fs.appendFile(this.ledgerPath, `${JSON.stringify(event)}\n`, 'utf8');
    const appendedEvents = appendTaskLedgerEvent(events, event).events;
    return {
      appended: true,
      event,
      view: projectTaskLedger(appendedEvents, event.workspaceId),
    };
  }

  async readEvents(): Promise<TaskLedgerEvent[]> {
    let contents: string;
    try {
      contents = await fs.readFile(this.ledgerPath, 'utf8');
    } catch (error) {
      if (isMissingFileError(error)) return [];
      throw error;
    }

    const events: TaskLedgerEvent[] = [];
    const lines = contents.split(/\r?\n/);
    for (const line of lines) {
      if (!line.trim()) continue;
      const parsed: unknown = JSON.parse(line);
      if (!isTaskLedgerEvent(parsed)) {
        throw new Error(`Invalid task ledger event in ${this.ledgerPath}`);
      }
      events.push(parsed);
    }
    return events;
  }

  async getWorkingContext(workspaceId: string): Promise<TaskLedgerWorkingContextView> {
    const events = await this.readEvents();
    if (!events.length) return emptyTaskLedgerWorkingContextView(workspaceId);
    return projectTaskLedger(events, workspaceId);
  }

  async project(workspaceId: string): Promise<TaskLedgerWorkingContextView> {
    return this.getWorkingContext(workspaceId);
  }
}

export function createTaskLedgerWorkingContext(
  options: TaskLedgerWorkingContextOptions,
): TaskLedgerWorkingContext {
  return new TaskLedgerWorkingContext(options);
}

export function isTaskLedgerEvent(value: unknown): value is TaskLedgerEvent {
  if (!value || typeof value !== 'object') return false;
  const candidate = value as Record<string, unknown>;\n  return (
    typeof candidate.eventId === 'string' &&
    typeof candidate.eventType === 'string' &&
    typeof candidate.workspaceId === 'string' &&
    typeof candidate.taskId === 'string' &&
    typeof candidate.occurredAt === 'string' &&
    (candidate.batchIdempotencyKey === undefined ||
      typeof candidate.batchIdempotencyKey === 'string')
  );
}

function isMissingFileError(error: unknown): boolean {
  return (
    error instanceof Error &&
    'code' in error &&
    (error as NodeJS.ErrnoException).code === 'ENOENT'
  );
}

